"""
QCB Token Tool  -  made by -gy

Watches the screen (nothing is injected into the game). When the match is over
it clicks, in order:   CONTINUE  ->  SKIP  ->  PLAY AGAIN   and repeats forever.
Queue your first match yourself, then press START.

Install:  pip install opencv-python mss pyautogui numpy
Run:      double-click START_QCB_TOKEN_TOOL.bat (after running setup/SETUP.bat once)
Use Windowed Fullscreen in Fortnite. Emergency stop: slam the mouse into the
top-left screen corner (pyautogui failsafe) or press STOP in the window.
"""
import base64
import ctypes
import threading
import time
import tkinter as tk
from tkinter import ttk

import cv2
import mss
import numpy as np
import pyautogui

# Make coordinates match real pixels on scaled displays (Windows)
try:
    ctypes.windll.shcore.SetProcessDpiAwareness(2)
except Exception:
    pass

pyautogui.FAILSAFE = True
pyautogui.PAUSE = 0.05

BG, PANEL, FG, ACCENT, GOOD, BAD = "#0f1220", "#181c33", "#e8eaf6", "#7c4dff", "#00e676", "#ff5252"

APP_NAME = "QCB Token Tool"
CREDIT = "made by -gy"

# Embedded logo (Sisyphus) so this stays a single file
LOGO_B64 = ""
ICON_B64 = ""

# ───────────────────── built-in button images ─────────────────────
# Cut from your screenshots (taken at REF_H pixels tall). The bot resizes them
# automatically to fit your screen, so there is nothing to capture.
REF_H = 1439
TEMPLATE_B64 = {
    "play_again": [
        "",
    ],
    "skip": [
        "",
    ],
    "continue": [
        "",
    ],
    "you_placed": [
        "",
        "",
    ],
    "recap": [
        "",
    ],
}

# Where to look on screen, as fractions of the screen: (left, top, right, bottom)
REGIONS = {
    "play_again": (0.50, 0.25, 1.00, 0.80),
    "skip": (0.65, 0.82, 1.00, 1.00),
    "continue": (0.65, 0.82, 1.00, 1.00),
    "you_placed": (0.15, 0.00, 0.85, 0.45),
    "recap": (0.00, 0.00, 0.45, 0.18),
}
SCALES = [0.55, 0.62, 0.70, 0.78, 0.86, 0.93, 1.0, 1.08, 1.17, 1.28, 1.40]


def _decode(b):
    return cv2.imdecode(np.frombuffer(base64.b64decode(b), np.uint8), cv2.IMREAD_GRAYSCALE)


TEMPLATES = {name: [_decode(b) for b in imgs] for name, imgs in TEMPLATE_B64.items()}


# ───────────────────────── vision helpers ─────────────────────────
def grab_screen():
    with mss.mss() as sct:
        shot = np.array(sct.grab(sct.monitors[1]))  # primary monitor
    return cv2.cvtColor(shot, cv2.COLOR_BGRA2GRAY)


def match(name, screen):
    """Best match of a built-in image on the screen -> (score, (x, y) center or None)."""
    h, w = screen.shape
    x0, y0, x1, y1 = REGIONS[name]
    ox, oy = int(x0 * w), int(y0 * h)
    roi = screen[oy:int(y1 * h), ox:int(x1 * w)]
    base = h / REF_H
    best = (0.0, None)
    for tpl in TEMPLATES[name]:
        for m in SCALES:
            s = base * m
            t = cv2.resize(tpl, None, fx=s, fy=s, interpolation=cv2.INTER_AREA if s < 1 else cv2.INTER_CUBIC)
            th, tw = t.shape
            if th < 6 or tw < 6 or th >= roi.shape[0] or tw >= roi.shape[1]:
                continue
            res = np.nan_to_num(cv2.matchTemplate(roi, t, cv2.TM_CCOEFF_NORMED))
            _, score, _, loc = cv2.minMaxLoc(res)
            if score > best[0]:
                best = (float(score), (ox + loc[0] + tw // 2, oy + loc[1] + th // 2))
    return best


def find(name, screen, threshold):
    score, pos = match(name, screen)
    return pos if score >= threshold else None


def click(pos):
    pyautogui.moveTo(pos[0], pos[1], duration=0.15)
    time.sleep(0.2)  # let the menu register the hover
    pyautogui.click()


# ───────────────────────── the bot ─────────────────────────
class Bot(threading.Thread):
    STEPS = (("play_again", "PLAY AGAIN"), ("skip", "SKIP"), ("continue", "CONTINUE"))

    def __init__(self, ui):
        super().__init__(daemon=True)
        self.ui = ui
        self.running = threading.Event()
        self.running.set()
        self.state = None
        self.rounds = 0
        self.started = time.time()

    def set_state(self, s):
        if s != self.state:
            self.state = s
            self.ui.set_state(s)

    def sleep(self, secs):
        end = time.time() + secs
        while self.running.is_set() and time.time() < end:
            time.sleep(0.1)

    def run(self):
        try:
            self.loop()
        except pyautogui.FailSafeException:
            self.ui.log("Failsafe triggered (mouse in corner). Stopped.")
        except Exception as e:
            self.ui.log(f"Error: {e!r}")
        self.ui.bot_stopped()

    def loop(self):
        self.ui.log("Bot started, watching for the end of the match")
        self.set_state("WATCHING")
        stuck = 0
        recap_miss = 0
        while self.running.is_set():
            thr = self.ui.threshold.get()
            screen = grab_screen()

            clicked = None
            for name, label in self.STEPS:
                hit = find(name, screen, thr)
                if hit:
                    click(hit)
                    clicked = name
                    self.ui.log(f"Clicked {label}")
                    break

            if clicked == "play_again":
                self.rounds += 1
                self.ui.set_rounds(self.rounds)
                self.set_state("QUEUE")
                stuck = recap_miss = 0
                self.sleep(10)
                self.set_state("WATCHING")
            elif clicked:
                self.set_state("POST-MATCH")
                stuck = recap_miss = 0
                self.sleep(2)
            else:
                placed = find("you_placed", screen, thr)
                recap = find("recap", screen, thr)
                if recap:
                    # On the recap screen but PLAY AGAIN wasn't seen
                    self.set_state("POST-MATCH")
                    recap_miss += 1
                    if recap_miss == 5:
                        self.ui.log("On the recap screen but can't see PLAY AGAIN. Try lowering the strictness slider.")
                elif placed:
                    # Continue/Skip screen but the button wasn't matched: try the Enter key
                    self.set_state("POST-MATCH")
                    stuck += 1
                    if stuck >= 4:
                        pyautogui.press("enter")
                        self.ui.log("Pressed ENTER (button not matched)")
                        stuck = 0
                else:
                    stuck = recap_miss = 0
                    self.set_state("WATCHING")

            self.ui.tick(time.time() - self.started)
            self.sleep(1.0)


# ───────────────────────── UI ─────────────────────────
class App:
    def __init__(self, root):
        self.root = root
        root.title(APP_NAME)
        self.icon_img = tk.PhotoImage(data=ICON_B64)
        root.iconphoto(True, self.icon_img)
        root.configure(bg=BG)
        root.geometry("560x700")
        root.resizable(False, False)
        self.bot = None
        self._rounds = 0
        self.threshold = tk.DoubleVar(value=0.75)

        style = ttk.Style()
        style.theme_use("clam")
        style.configure("TFrame", background=PANEL)
        style.configure("TLabel", background=PANEL, foreground=FG, font=("Segoe UI", 10))
        style.configure("TButton", background=ACCENT, foreground="white", font=("Segoe UI", 10, "bold"), borderwidth=0, padding=6)
        style.map("TButton", background=[("active", "#9575ff")])
        style.configure("TScale", background=PANEL)

        head = tk.Frame(root, bg=BG)
        head.pack(pady=(12, 0))
        self.logo_img = tk.PhotoImage(data=LOGO_B64)
        tk.Label(head, image=self.logo_img, bg=BG).pack(side="left", padx=(0, 14))
        tk.Label(head, text="QCB TOKEN TOOL", bg=BG, fg=ACCENT, font=("Segoe UI", 22, "bold")).pack(side="left")

        self.state_lbl = tk.Label(root, text="IDLE", bg=BG, fg=FG, font=("Segoe UI", 28, "bold"))
        self.state_lbl.pack(pady=(6, 0))
        self.timer_lbl = tk.Label(root, text="running 00:00  ·  rounds: 0", bg=BG, fg="#9fa8da", font=("Segoe UI", 11))
        self.timer_lbl.pack(pady=(0, 8))

        flow = ttk.Frame(root, padding=10)
        flow.pack(fill="x", padx=14, pady=4)
        ttk.Label(flow, text="When the match is over the bot clicks:", font=("Segoe UI", 11, "bold")).pack(anchor="w")
        chips = tk.Frame(flow, bg=PANEL)
        chips.pack(anchor="w", pady=6)
        for txt in ("1  CONTINUE", "2  SKIP", "3  PLAY AGAIN"):
            tk.Label(chips, text=txt, bg=ACCENT, fg="white", font=("Segoe UI", 10, "bold"), padx=10, pady=4).pack(side="left", padx=(0, 6))
        ttk.Label(flow, text="Queue your first match yourself, then press START.").pack(anchor="w")

        sb = ttk.Frame(root, padding=10)
        sb.pack(fill="x", padx=14, pady=4)
        ttk.Label(sb, text="Match strictness", font=("Segoe UI", 10, "bold")).grid(row=0, column=0, sticky="w")
        ttk.Scale(sb, from_=0.5, to=0.95, variable=self.threshold, length=220).grid(row=0, column=1, padx=10)
        self.thr_lbl = ttk.Label(sb, text="0.75")
        self.thr_lbl.grid(row=0, column=2)
        self.threshold.trace_add("write", lambda *_: self.thr_lbl.config(text=f"{self.threshold.get():.2f}"))

        cb = tk.Frame(root, bg=BG)
        cb.pack(pady=8)
        self.start_btn = ttk.Button(cb, text="▶ START (5s delay)", command=self.start)
        self.start_btn.pack(side="left", padx=6)
        self.stop_btn = ttk.Button(cb, text="■ STOP", command=self.stop, state="disabled")
        self.stop_btn.pack(side="left", padx=6)
        ttk.Button(cb, text="Test detection", command=self.test).pack(side="left", padx=6)

        tk.Label(root, text=CREDIT, bg=BG, fg="#5c6bc0", font=("Segoe UI", 8)).pack(side="bottom", pady=(0, 6))
        self.logbox = tk.Text(root, height=10, bg="#0a0d1a", fg="#b0bec5", font=("Consolas", 9), bd=0, state="disabled")
        self.logbox.pack(fill="both", expand=True, padx=14, pady=(4, 6))
        self.log(f"{APP_NAME} ready")

    # ---- thread-safe UI helpers
    def log(self, msg):
        def _do():
            self.logbox.config(state="normal")
            self.logbox.insert("end", f"[{time.strftime('%H:%M:%S')}] {msg}\n")
            self.logbox.see("end")
            self.logbox.config(state="disabled")
        self.root.after(0, _do)

    def set_state(self, s):
        colors = {"WATCHING": "#40c4ff", "POST-MATCH": "#ffd740", "QUEUE": GOOD}
        self.root.after(0, lambda: self.state_lbl.config(text=s, fg=colors.get(s, FG)))

    def set_rounds(self, n):
        self._rounds = n

    def tick(self, secs):
        m, s = divmod(int(secs), 60)
        h, m = divmod(m, 60)
        t = f"{h}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"
        self.root.after(0, lambda: self.timer_lbl.config(text=f"running {t}  ·  rounds: {self._rounds}"))

    # ---- actions
    def test(self):
        self.log("Test in 5 seconds: switch to the screen you want to check")
        self.root.after(5000, self._run_test)

    def _run_test(self):
        screen = grab_screen()
        thr = self.threshold.get()
        parts = []
        for name in TEMPLATES:
            score, _ = match(name, screen)
            parts.append(f"{name} {score:.2f}{'✔' if score >= thr else '✘'}")
        self.log("Scores: " + " | ".join(parts))

    def start(self):
        self.start_btn.config(state="disabled")
        self.stop_btn.config(state="normal")
        self.log("Starting in 5 seconds, switch to Fortnite")
        self.root.after(5000, self._launch)

    def _launch(self):
        if str(self.stop_btn["state"]) == "disabled":
            return
        self.bot = Bot(self)
        self.bot.start()

    def stop(self):
        if self.bot:
            self.bot.running.clear()
        self.bot_stopped()

    def bot_stopped(self):
        def _do():
            self.start_btn.config(state="normal")
            self.stop_btn.config(state="disabled")
            self.state_lbl.config(text="IDLE", fg=FG)
            self.log("Stopped")
        self.root.after(0, _do)


if __name__ == "__main__":
    root = tk.Tk()
    App(root)
    root.mainloop()
